"use client"
import React, { useEffect, useState } from "react"
import axios from "axios"
import Link from "next/link"
import { toast } from 'react-hot-toast'
import { useRouter } from 'next/navigation'
import AddTodoForm from "./AddTodoForm"

export default function Dashboard() {
  const router = useRouter()

  // State variables
  const [user, setUser]:any = useState(null)
  const [todos, setTodos] = useState([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)

  // Fetch the current user
  const getCurrentUser = async () => {
    try {
      const response = await axios.get("/api/auth/me")
      setUser(response.data.user)
    } catch {
      router.push("/login") // Redirect to login if user is not authenticated
    }
  }

  // Fetch todos for the current user
  const getTodos = async () => {
    if (!user?._id) return // Return if user doesn't have an ID
    setLoading(true) // Set loading state to true before fetching todos

    try {
      const response = await axios.get(`/api/todos?userId=${user._id}`)
      setTodos(response.data.data) // Set todos from the API response
    } catch {
      toast.error("Failed to load todos") // Show error message if fetch fails
    } finally {
      setLoading(false) // Set loading state to false after fetching
    }
  }

  // Handle adding new todo
  const onTodoAdded = () => {
    getTodos() // Fetch the updated list of todos after adding a new one
    setShowForm(false) // Close the form after adding the todo
  }

  // Fetch the current user on mount
  useEffect(() => {
    getCurrentUser()
  }, [])

  // Fetch todos whenever the user changes
  useEffect(() => {
    if (user?._id) {
      getTodos()
    }
  }, [user])

  return (
    <div className="min-h-screen bg-gray-950 text-white flex flex-col md:flex-row">
      
      {/* Sidebar */}
     

      {/* Main content */}
      <main className="flex-1 p-6 overflow-y-auto">
        <header className="flex items-center justify-between mb-6">
          <h1 className="text-3xl font-semibold">Dashboard</h1>
          
          {/* Add Task Button */}
          <button 
            onClick={() => setShowForm(true)} 
            className="bg-blue-600 px-4 py-2 rounded-lg hover:bg-blue-700"
          >
            Add Task
          </button>
        </header>

        {/* Add Todo Form Modal */}
        {showForm && (
          <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
            <AddTodoForm 
              userId={user?._id} 
              onClose={() => setShowForm(false)} 
              onTodoAdded={onTodoAdded} // Passing the onTodoAdded handler as a prop
            />
          </div>
        )}

        {/* Loading Spinner */}
        {loading ? (
          <div className="flex justify-center items-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
          </div>
        ) : (
          // Display Todos
          todos.length ? (
            <section className="grid gap-6 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
              {todos.map(todo => (
                <div key={todo._id} className="bg-gray-800 p-4 rounded-lg shadow hover:shadow-lg transition-transform transform hover:scale-105">
                  <h2 className="text-xl font-bold mb-2">{todo.title}</h2>
                  <p className="text-sm text-gray-400 mb-2">Due: {new Date(todo.deadline).toLocaleDateString()}</p>
                  <p className="text-sm text-gray-300 mb-4">{todo.description}</p>
                  <span className={`text-xs px-2 py-1 rounded-full ${todo.status === 'completed' ? 'bg-green-500' : 'bg-yellow-500'}`}>
                    {todo.status}
                  </span>
                </div>
              ))}
            </section>
          ) : (
            // No todos message
            <p className="text-center py-10 text-gray-400">No TODOs available. Create your first task!</p>
          )
        )}
      </main>
    </div>
  )
}
